export function thumbUrl(exerciseId: string): string | null {
  const v = V3_EXERCISE_THUMBS[exerciseId];
  return v ? `https://res.cloudinary.com/${V3_THUMB_CLOUD}/image/upload/${v}/${V3_THUMB_FOLDER}/${exerciseId}.jpg` : null;
}
